#include "stdlib/math/base/special/round2f.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/assert/is_infinitef.h"
#include "stdlib/math/base/special/frexpf.h"
#include "stdlib/math/base/special/ldexpf.h"

#include <stdint.h>

/**
* Rounds a single-precision floating-point value to the nearest power of two
* on a linear scale.
*
* @param x    input value
* @return     rounded value
*
* @example
* float out = stdlib_base_round2f( 3.14f );
* // returns 4.0f
*/
float stdlib_base_round2f( const float x ) {
	int32_t exp;
	float frac;
	float sign;
	float y;

	// Handle special cases:
	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_infinitef( x ) || x == 0.0f ) {
		return x;
	}

	// Preserve sign:
	if ( x < 0.0f ) {
		sign = -1.0f;
	} else {
		sign = 1.0f;
	}

	// Decompose |x| = frac * 2^exp, frac in [0.5, 1):
	stdlib_base_frexpf( sign * x, &frac, &exp );

	// Decide nearest power of two:
	if ( frac < 0.75f ) {
		y = stdlib_base_ldexpf( 1.0f, exp-1 );
	} else {
		y = stdlib_base_ldexpf( 1.0f, exp );
	}

	return sign * y;
}
